     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Terms Consent</title>
     <style>
       :root {
         color-scheme: light;
         --bg: #f4f7fb;
         --surface: rgba(255, 255, 255, 0.9);
         --surface-border: rgba(148, 163, 184, 0.22);
         --text: #0f172a;
         --muted: #64748b;
         --accent: #2563eb;
         --accent-hover: #1d4ed8;
         --shadow: 0 20px 60px rgba(15, 23, 42, 0.12);
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         color: var(--text);
         background:
           radial-gradient(circle at top, rgba(37, 99, 235, 0.12), transparent 35%),
           linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
         display: grid;
         place-items: center;
         padding: 24px;
       }

       .card {
         width: min(100%, 460px);
         background: var(--surface);
         border: 1px solid var(--surface-border);
         border-radius: 24px;
         box-shadow: var(--shadow);
         backdrop-filter: blur(14px);
         padding: 32px;
       }

       .eyebrow {
         margin: 0 0 8px;
         font-size: 0.82rem;
         font-weight: 700;
         letter-spacing: 0.08em;
         text-transform: uppercase;
         color: var(--accent);
       }

       h1 {
         margin: 0 0 12px;
         font-size: 1.7rem;
         line-height: 1.2;
       }

       .description {
         margin: 0 0 24px;
         color: var(--muted);
         line-height: 1.6;
       }

       form {
         display: grid;
         gap: 20px;
       }

       .form-field {
         display: flex;
         gap: 12px;
         align-items: flex-start;
         padding: 16px;
         border-radius: 16px;
         border: 1px solid rgba(148, 163, 184, 0.18);
         background: rgba(248, 250, 252, 0.72);
       }

       .checkbox-wrap {
         display: grid;
         gap: 6px;
       }

       label {
         font-weight: 600;
         line-height: 1.4;
         cursor: pointer;
       }

       .helper-text {
         margin: 0;
         font-size: 0.92rem;
         line-height: 1.5;
         color: var(--muted);
       }

       input[type="checkbox"] {
         width: 18px;
         height: 18px;
         margin-top: 2px;
         accent-color: var(--accent);
         cursor: pointer;
         flex: 0 0 auto;
       }

       button {
         appearance: none;
         border: 0;
         border-radius: 12px;
         padding: 14px 18px;
         font: inherit;
         font-weight: 700;
         color: white;
         background: linear-gradient(135deg, var(--accent), #1e40af);
         cursor: pointer;
         box-shadow: 0 10px 24px rgba(37, 99, 235, 0.24);
         transition: transform 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
       }

       button:hover {
         background: linear-gradient(135deg, var(--accent-hover), #1e3a8a);
         transform: translateY(-1px);
         box-shadow: 0 14px 28px rgba(37, 99, 235, 0.28);
       }

       button:active {
         transform: translateY(0);
       }

       .status {
         min-height: 1.25rem;
         margin: 0;
         font-size: 0.95rem;
         color: #166534;
       }
     </style>
   </head>
   <body>
     <main class="card">
       <p class="eyebrow">Account setup</p>
       <h1>Review and accept the terms</h1>
       <p class="description">Please confirm you agree to the terms of use before continuing.</p>

       <form id="consent-form" novalidate>
         <div class="form-field">
           <input id="terms" name="terms" type="checkbox" required />
           <div class="checkbox-wrap">
             <label for="terms">I agree to the Terms of Use</label>
             <p class="helper-text">You must agree to proceed with your submission.</p>
           </div>
         </div>

         <button type="submit">Continue</button>
         <p class="status" id="status" aria-live="polite"></p>
       </form>
     </main>

     <script>
       const form = document.getElementById("consent-form");
       const checkbox = document.getElementById("terms");
       const status = document.getElementById("status");

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         if (!checkbox.checked) {
           status.textContent = "Please accept the terms to continue.";
           status.style.color = "#b91c1c";
           checkbox.focus();
           return;
         }

         status.textContent = "Thanks — your consent has been recorded.";
         status.style.color = "#166534";
       });
     </script>
   </body>
 </html>

')
